// Deterministic 2-day rotation: advances one slot (and one image) every 2 days.
const DAY = 86400000;
const slot = Math.floor(Math.floor(Date.now() / DAY) / 2);

const LINK = 'https://play.google.com/store/apps/details?id=com.bedrockproxy';
const R2 = 'https://social.bedrockbroadcaster.com/posts/';

// Rotating library: reframed marketing scene cards (headline baked into the image) +
// the 1:1 brand square. Captions COMPLEMENT the on-image headline, they do not repeat it.
const POSTS = [
  { img: R2 + 'scene-broadcast.png', hook: 'Turn any Bedrock server into a LAN server your console can see. \uD83C\uDFAE', body: 'PS4, PS5, Xbox, Switch & Windows \u2014 no PC middleman, no fuss.' },
  { img: R2 + 'scene-live.png',      hook: 'From tap to in-game in seconds. \u26A1',                                  body: 'Pick a server, hit connect, and your console is in.' },
  { img: R2 + 'scene-friends.png',   hook: 'Get the whole squad on the same server. \uD83D\uDC7E',                    body: 'Console, mobile and PC all playing together on Bedrock.' },
  { img: R2 + 'scene-saved.png',     hook: 'Save your servers, reconnect in one tap. \uD83D\uDD16',                   body: 'No re-typing IPs every single session.' },
  { img: R2 + 'scene-packs.png',     hook: 'Bring your own resource packs \u2014 free. \u2728',                     body: 'Servers push their packs straight to your console. No paywall.' },
  { img: R2 + 'brand-square.png',    hook: 'Play Bedrock on your console, the easy way. \uD83C\uDFAE',              body: 'Switch support. Free packs. Close the app once you have joined.' }
];

// Layered hashtag pools (broad reach -> mid -> platform-niche -> branded intent).
const BROAD    = ['#minecraft','#minecraftbedrock','#gaming','#minecraftcommunity','#bedrock'];
const MID      = ['#bedrockserver','#minecraftconsole','#minecraftserver','#bedrockedition','#minecraftbedrockedition','#mcpe','#minecraftmultiplayer'];
const PLATFORM = ['#ps4minecraft','#ps5minecraft','#xboxminecraft','#switchminecraft','#minecraftswitch','#minecraftxbox','#minecraftps5','#consolegaming'];
const BRAND    = ['#bedrockbroadcaster','#playbedrock','#minecraftservers'];

function rotate(arr, n, count){ const out=[]; for(let i=0;i<count && i<arr.length;i++){ out.push(arr[((n+i)%arr.length+arr.length)%arr.length]); } return out; }

const post = POSTS[((slot % POSTS.length)+POSTS.length)%POSTS.length];

// Rotate hashtag subsets so each post reaches different discovery pools.
const igTags = [...new Set([
  ...BRAND,
  ...rotate(BROAD, slot, 4),
  ...rotate(MID, slot, 5),
  ...rotate(PLATFORM, slot, 6)
])].slice(0, 28);
const fbTags = [...new Set([BRAND[0], ...rotate(BROAD, slot, 2)])];

const image_url = post.img;
const ig_caption = post.hook + '\n\n' + post.body + '\n\n\uD83D\uDC49 Get it free: ' + LINK + '\n\n' + igTags.join(' ');
const fb_caption = post.hook + '\n\n' + post.body + '\n\n\uD83D\uDC49 Get it free: ' + LINK + '\n\n' + fbTags.join(' ');

return [{ json: { slot, angle: post.hook, image_url, ig_caption, fb_caption } }];

// Publishes to Instagram (2-step create -> poll -> publish) and Facebook (best-effort).
// Params are passed via the `qs` option so n8n URL-encodes exactly once (hand-built
// encoded URLs get double-encoded -> HTTP 400).
const helpers = this.helpers;
const token = $env.META_PAGE_TOKEN;
const IG = $env.IG_ACCOUNT_ID;
const FB = $env.FB_PAGE_ID;
const { image_url, ig_caption, fb_caption, angle, slot } = $input.first().json;
const G = 'https://graph.facebook.com/v23.0';
const req = (method, path, params) => helpers.httpRequest({ method, url: `${G}/${path}`, qs: params, json: true });
const errmsg = (e) => {
  const b = e.response && (e.response.body || e.response.data);
  if (b && b.error) return JSON.stringify(b.error);
  if (b) return (typeof b === 'string' ? b : JSON.stringify(b)).slice(0, 300);
  return (e && e.message) ? e.message : String(e);
};

if (!token || !IG) throw new Error('Missing META_PAGE_TOKEN or IG_ACCOUNT_ID in env (restart pod after secret update).');

const result = { slot, angle, image_url, ig: {}, fb: {} };

// --- Instagram ---
try {
  const c = await req('POST', `${IG}/media`, { image_url, caption: ig_caption, access_token: token });
  const creationId = c.id;
  let status = 'IN_PROGRESS';
  for (let i = 0; i < 12 && status !== 'FINISHED'; i++) {
    await new Promise(r => setTimeout(r, 5000));
    const s = await req('GET', creationId, { fields: 'status_code', access_token: token });
    status = s.status_code;
    if (status === 'ERROR') throw new Error('IG container processing ERROR');
  }
  if (status !== 'FINISHED') throw new Error('IG container not ready (last status: ' + status + ')');
  const p = await req('POST', `${IG}/media_publish`, { creation_id: creationId, access_token: token });
  result.ig = { ok: true, id: p.id };
  try { const pl = await req('GET', p.id, { fields: 'permalink', access_token: token }); result.ig.permalink = pl.permalink; } catch (_) {}
} catch (e) { result.ig = { ok: false, error: errmsg(e) }; }

// --- Facebook (needs pages_manage_posts; reports a clear error until granted) ---
try {
  const f = await req('POST', `${FB}/photos`, { url: image_url, caption: fb_caption, access_token: token });
  result.fb = { ok: true, id: f.id || f.post_id };
} catch (e) { result.fb = { ok: false, error: errmsg(e) }; }

return [{ json: result }];
